messages.content:
Tool response:
Tool: submit_refinance_application
Description: Submit Refinance Application
Parameters:
    {
      "type": "object",
      "properties": {
        "vehicle_vin": {
          "type": "string",
          "description": "VIN of the vehicle to refinance",
          "title": "Vehicle Vin"
        },
        "requested_amount": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Requested Amount"
        },
        "term_months": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Term Months"
        },
        "target_monthly_payment": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Target Monthly Payment"
        },
        "first_payment_date": {
          "type": "string",
          "title": "First Payment Date"
        }
      },
      "required": [
        "vehicle_vin",
        "requested_amount",
        "term_months",
        "first_payment_date"
      ]
    }
